ScanKit scanKit;

@override
void initState() {
  super.initState();
  scanKit = ScanKit();
  scanKit!.onResult.listen((val) {
    debugPrint("scanning result:${val.originalValue}  scanType:${val.scanType}");
  });
}

Future<void> startScan() async {
  try {
    await scanKit?.startScan();
  } on PlatformException {}
}
